mapper.select:
SELECT
COUNT(*) AS chatCount,
COALESCE(SUM(f.total_tokens), 0) AS totalTokens,
COALESCE(SUM(f.prompt_tokens), 0) AS promptTokens,
COALESCE(SUM(f.completion_tokens), 0) AS completionTokens,
COUNT(DISTINCT DATE(f.created_at)) AS activeDays
FROM ai_conversation_usage_fact f
WHERE f.tenant_id = #{params.tenantId}

    AND f.username = #{params.userId}


    AND DATE(f.created_at) >= #{params.startDate}


    AND DATE(f.created_at) <= #{params.endDate}

SELECT DATE(f.created_at) AS date, COUNT(*) AS chatCount FROM ai_conversation_usage_fact f WHERE f.tenant_id = #{params.tenantId}
AND f.username = #{params.userId}
AND f.created_at >= CONCAT(#{params.startDate}, ' 00:00:00')
AND f.created_at < DATE_ADD(#{params.endDate}, INTERVAL 1 DAY)
GROUP BY DATE(f.created_at) ORDER BY DATE(f.created_at)

SELECT f.model AS modelName, COUNT(*) AS chatCount, COALESCE(SUM(f.total_tokens), 0) AS totalTokens, COALESCE(SUM(f.prompt_tokens), 0) AS promptTokens, COALESCE(SUM(f.completion_tokens), 0) AS completionTokens FROM ai_conversation_usage_fact f WHERE f.tenant_id = #{params.tenantId} AND f.model IS NOT NULL
AND f.model = #{params.modelName}
AND DATE(f.created_at) BETWEEN #{params.startDate} AND #{params.endDate} GROUP BY f.model ORDER BY totalTokens DESC

  SELECT r.conversation_id AS conversationId,
         r.dataset_id AS datasetId,
         r.agent_id AS agentId,
       a.name AS agentName,
       r.question_text AS questionText,
       r.create_time AS createTime
FROM ai_chat_record r
LEFT JOIN ai_agent a ON r.agent_id = a.id AND a.del_flag = '0'
WHERE r.del_flag = '0'
  AND r.tenant_id = #{params.tenantId}
    AND r.username = #{params.userId}

        AND r.dataset_id = #{params.datasetId}

    AND r.conversation_id IS NOT NULL
  AND r.question_text != ''
  AND r.record_id IN (
      SELECT MAX(r2.record_id)
      FROM ai_chat_record r2
      WHERE r2.del_flag = '0'
        AND r2.tenant_id = #{params.tenantId}
          AND r2.username = #{params.userId}

              AND r2.dataset_id = #{params.datasetId}

          AND r2.conversation_id IS NOT NULL
      GROUP BY r2.conversation_id
  )
ORDER BY r.create_time DESC
LIMIT #{params.limit}

