WHERE r.del_flag = '0'
AND r.tenant_id = #{query.tenantId}
AND r.create_time >= #{query.startTime}
AND r.create_time <= #{query.endTime}

	AND (r.username LIKE CONCAT('%', #{query.userKeyword}, '%')
		 OR u.name LIKE CONCAT('%', #{query.userKeyword}, '%'))

AND u.dept_id = #{query.deptId}
AND r.agent_id = #{query.agentId}

	AND r.llm_flag = #{query.responseStatus}

AND (r.evaluate IS NULL OR r.evaluate = '') 

	AND r.evaluate = #{query.evaluate}


	AND r.question_text LIKE CONCAT('%', #{query.questionKeyword}, '%')


	AND r.conversation_id = #{query.conversationId}


	AND r.message_id = #{query.messageId}
